('w:palmeira','b1','a palmeira','сущ.','пальма','Há palmeiras ao longo de toda a avenida.','Вдоль всего проспекта растут пальмы.','','B1','B2',380,'пальма','Уздовж усього проспекту ростуть пальми.',''),
('w:palpite','b1','o palpite','сущ.','догадка, предчувствие','Tenho um palpite de que ela vai aceitar.','У меня есть предчувствие, что она согласится.','','B1','A8',381,'здогад, передчуття','У мене є передчуття, що вона погодиться.',''),
('w:pânico','b1','o pânico','сущ.','паника','Houve pânico quando as luzes se apagaram.','Началась паника, когда погас свет.','','B1','B1',382,'паніка','Почалася паніка, коли згасло світло.',''),
('w:paraíso','b1','o paraíso','сущ.','рай','Aquela praia deserta é um verdadeiro paraíso.','Тот безлюдный пляж — настоящий рай.','','B1','A1',383,'рай','Той безлюдний пляж — справжній рай.',''),
('w:parecido','b1','parecido','прил.','похожий','O teu casaco é parecido com o meu.','Твоя куртка похожа на мою.','parecido com','B1','A9',384,'схожий','Твоя куртка схожа на мою.','parecido com'),
('w:participante','b1','o participante','сущ.','участник','Cada participante recebeu um certificado no fim.','Каждый участник в конце получил сертификат.','','B1','B4',385,'учасник','Кожен учасник наприкінці отримав сертифікат.',''),
('w:parto','b1','o parto','сущ.','роды','O parto correu bem e a mãe já está em casa.','Роды прошли хорошо, и мать уже дома.','','B1','B6',386,'пологи','Пологи минули добре, і мати вже вдома.',''),
('w:pastor','b1','o pastor','сущ.','пастух; пастор','O pastor levava as ovelhas para a serra ao amanhecer.','Пастух гнал овец в горы на рассвете.','','B1','B3',387,'пастух; пастор','Пастух гнав овець у гори на світанку.',''),
('w:patrão','b1','o patrão','сущ.','хозяин, начальник','O patrão deu-nos a tarde de sexta livre.','Начальник дал нам свободную вторую половину пятницы.','','B1','B3',388,'хазяїн, роботодавець','Начальник дав нам вільну другу половину п’ятниці.',''),
('w:pecado','b1','o pecado','сущ.','грех','Deitar comida fora é um pecado, dizia a avó.','Выбрасывать еду — грех, говорила бабушка.','','B1','B1',389,'гріх','Викидати їжу — гріх, казала бабуся.',''),
('w:perdão','b1','o perdão','сущ.','прощение','Pediu perdão à irmã depois da discussão.','Он попросил у сестры прощения после ссоры.','','B1','B1',390,'прощення','Він попросив у сестри прощення після сварки.',''),
('w:perdido','b1','perdido','прил.','потерянный; заблудившийся','Andámos perdidos no centro durante uma hora.','Мы час плутали по центру.','','B1','A2',391,'загублений; заблуканий','Ми годину блукали центром.',''),
('w:permitido','b1','permitido','прил.','разрешённый','Não é permitido fumar dentro do restaurante.','Курить внутри ресторана запрещено.','','B1','A7',392,'дозволений','Палити всередині ресторану заборонено.',''),
('w:persistir','b1','persistir','глаг.','упорствовать; сохраняться','A dor persistiu durante mais de uma semana.','Боль сохранялась больше недели.','','B1','A4',393,'наполягати; зберігатися','Біль зберігався понад тиждень.',''),
('w:pesadelo','b1','o pesadelo','сущ.','кошмар','A viagem de regresso foi um verdadeiro pesadelo.','Обратная дорога была настоящим кошмаром.','','B1','B6',394,'кошмар, страхіття','Зворотна дорога була справжнім кошмаром.',''),
('w:pescar','b1','pescar','глаг.','ловить рыбу','O meu tio vai pescar todos os domingos de manhã.','Мой дядя ходит на рыбалку каждое воскресное утро.','','B1','B4',395,'ловити рибу','Мій дядько ходить на риболовлю щонедільного ранку.',''),
('w:péssimo','b1','péssimo','прил.','отвратительный, худший','O serviço daquele café é péssimo, nunca mais lá volto.','Обслуживание в том кафе отвратительное, больше туда ни ногой.','Превосходная степень от mau','B1','A7',396,'препоганий, найгірший','Обслуговування в тому кафе препогане, більше туди ні ногою.','Найвищий ступінь від mau'),
('w:pessoalmente','b1','pessoalmente','нареч.','лично','Prefiro tratar deste assunto pessoalmente, não por email.','Я предпочитаю уладить это лично, а не по почте.','','B1','A9',397,'особисто','Я волію владнати це особисто, а не поштою.',''),
('w:petróleo','b1','o petróleo','сущ.','нефть','O preço do petróleo subiu outra vez.','Цена на нефть снова выросла.','','B1','B2',398,'нафта','Ціна на нафту знову зросла.',''),
('w:piada','b1','a piada','сущ.','шутка, анекдот','Ele contou uma piada e ninguém se riu.','Он рассказал анекдот, и никто не засмеялся.','','B1','B4',399,'жарт, анекдот','Він розповів анекдот, і ніхто не засміявся.','')
insert into public.pt_words (id, deck_id, word, pos, ru, ex, exru, note, level, tema, sort, uk, exuk, noteuk) values
('w:pista','b1','a pista','сущ.','след, зацепка; дорожка','A polícia ainda não tem nenhuma pista.','У полиции пока нет ни одной зацепки.','','B1','A8',400,'слід, зачіпка; доріжка','У поліції поки немає жодної зачіпки.',''),
('w:poço','b1','o poço','сущ.','колодец','A casa antiga ainda tem um poço no quintal.','В старом доме во дворе ещё есть колодец.','','B1','B2',401,'криниця','У старому домі на подвір’ї ще є криниця.',''),
('w:polémica','b1','a polémica','сущ.','полемика, спор','A decisão do árbitro gerou muita polémica.','Решение судьи вызвало много споров.','Европейское написание, с -é-','B1','A8',402,'полеміка, суперечка','Рішення арбітра викликало багато суперечок.','Європейське написання, з -é-'),
('w:pontapé','b1','o pontapé','сущ.','пинок, удар ногой','Deu um pontapé na bola com toda a força.','Он изо всех сил ударил по мячу.','','B1','B4',403,'стусан, удар ногою','Він щосили вдарив по м’ячу.',''),
('w:porcaria','b1','a porcaria','сущ.','гадость, дрянь','Não comas essa porcaria antes do jantar.','Не ешь эту гадость перед ужином.','Очень частое разговорное','B1','A7',404,'гидота, погань','Не їж цю гидоту перед вечерею.','Дуже часте розмовне'),
('w:portaria','b1','a portaria','сущ.','вахта, стойка портье','Deixei a encomenda na portaria do prédio.','Я оставил посылку на вахте дома.','','B1','B5',405,'вахта, стійка портьє','Я залишив посилку на вахті будинку.',''),
('w:potencial','b1','o potencial','сущ.','потенциал','Aquele jogador tem muito potencial, mas falta-lhe disciplina.','У того игрока большой потенциал, но не хватает дисциплины.','','B1','A7',406,'потенціал','У того гравця великий потенціал, але бракує дисципліни.',''),
('w:preferido','b1','preferido','прил.','любимый, предпочитаемый','Este é o meu restaurante preferido em Lisboa.','Это мой любимый ресторан в Лиссабоне.','','B1','A7',407,'улюблений','Це мій улюблений ресторан у Лісабоні.',''),
('w:prejuízo','b1','o prejuízo','сущ.','ущерб, убыток','A tempestade causou prejuízos enormes na agricultura.','Буря нанесла огромный ущерб сельскому хозяйству.','','B1','A7',408,'збиток, шкода','Буря завдала величезних збитків сільському господарству.',''),
('w:prenda','b1','a prenda','сущ.','подарок','Comprei uma prenda de anos para a minha afilhada.','Я купил подарок на день рождения крестнице.','Европейское слово; бразильцы говорят presente','B1','B7',409,'подарунок','Я купив подарунок на день народження хрещениці.','Європейське слово; бразильці кажуть presente'),
('w:presépio','b1','o presépio','сущ.','рождественский вертеп','Montámos o presépio no início de dezembro.','Мы поставили вертеп в начале декабря.','Обязательная часть португальского Рождества','B1','B4',410,'різдвяний вертеп','Ми поставили вертеп на початку грудня.','Обов’язкова частина португальського Різдва'),
('w:pressa','b1','a pressa','сущ.','спешка','Estou com pressa, falamos logo à noite.','Я тороплюсь, поговорим вечером.','estar com pressa','B1','A4',411,'поспіх','Я поспішаю, поговоримо ввечері.','estar com pressa'),
('w:prestação','b1','a prestação','сущ.','взнос, платёж','Pagamos o carro em trinta e seis prestações.','Мы платим за машину тридцатью шестью взносами.','','B1','B9',412,'внесок, виплата','Ми платимо за машину тридцятьма шістьма внесками.',''),
('w:prestes','b1','prestes','прил.','готовый вот-вот','O comboio estava prestes a partir quando cheguei.','Поезд уже отходил, когда я пришёл.','estar prestes a + инфинитив','B1','A4',413,'готовий ось-ось','Потяг уже відходив, коли я прийшов.','estar prestes a + інфінітив'),
('w:pretender','b1','pretender','глаг.','намереваться','Pretendo mudar de emprego no próximo ano.','Я намерен сменить работу в следующем году.','Ложный друг: это не «притворяться»','B1','A8',414,'мати намір','Я маю намір змінити роботу наступного року.','Хибний друг: це не «удавати»'),
('w:primário','b1','primário','прил.','начальный, первичный','A minha filha anda no ensino primário.','Моя дочь учится в начальной школе.','','B1','A4',415,'початковий, первинний','Моя донька навчається в початковій школі.',''),
('w:prisioneiro','b1','o prisioneiro','сущ.','заключённый, пленник','Os prisioneiros trabalhavam na horta da cadeia.','Заключённые работали в тюремном огороде.','','B1','B9',416,'в’язень, полонений','В’язні працювали на тюремному городі.',''),
('w:privacidade','b1','a privacidade','сущ.','частная жизнь, приватность','Toda a gente tem direito à sua privacidade.','Каждый имеет право на частную жизнь.','','B1','B1',417,'приватність','Кожен має право на приватність.',''),
('w:proporcionar','b1','proporcionar','глаг.','предоставлять, доставлять','A viagem proporcionou-nos momentos inesquecíveis com a família toda.','Поездка подарила нам незабываемые моменты со всей семьёй.','','B1','A9',418,'надавати, дарувати','Подорож подарувала нам незабутні миті з усією родиною.',''),
('w:provisório','b1','provisório','прил.','временный','Arranjaram uma solução provisória até ao verão.','Они нашли временное решение до лета.','','B1','A4',419,'тимчасовий','Вони знайшли тимчасове рішення до літа.',''),
