('w:lamentar','b1','lamentar','глаг.','сожалеть','Lamento imenso, mas não vou conseguir ir.','Мне очень жаль, но прийти не получится.','Вежливая формула отказа','B1','B1',791,'шкодувати','Мені дуже шкода, але прийти не вийде.','Ввічлива формула відмови'),
('w:lançar','b1','lançar','глаг.','выпускать, запускать','A editora lançou o livro na feira do Porto.','Издательство выпустило книгу на ярмарке в Порту.','lançar-se — броситься, взяться за что-то','B1','A2',792,'випускати, запускати','Видавництво випустило книжку на ярмарку в Порту.','lançar-se — кинутися, узятися за щось'),
('w:limitar','b1','limitar','глаг.','ограничивать','O médico limitou-lhe o sal e o café.','Врач ограничил ему соль и кофе.','limitar-se a — ограничиться чем-то','B1','A5',793,'обмежувати','Лікар обмежив йому сіль і каву.','limitar-se a — обмежитися чимось'),
('w:negociar','b1','negociar','глаг.','вести переговоры, договариваться','Negociámos o preço da renda com o senhorio.','Мы договорились с хозяином о цене аренды.','','B1','B9',794,'вести перемовини, торгуватися','Ми домовилися з господарем про ціну оренди.',''),
('w:ocupar','b1','ocupar','глаг.','занимать место или время','O sofá ocupa metade da sala de estar.','Диван занимает половину гостиной.','ocupar-se de — заниматься чем-то','B1','A2',795,'займати місце чи час','Диван займає половину вітальні.','ocupar-se de — займатися чимось'),
('w:organizar','b1','organizar','глаг.','организовывать, устраивать','Organizaram um jantar para toda a equipa.','Они устроили ужин для всей команды.','','B1','B3',796,'організовувати, влаштовувати','Вони влаштували вечерю для всієї команди.',''),
('w:prejudicar','b1','prejudicar','глаг.','вредить, наносить ущерб','O ruído prejudica o sono de toda a família.','Шум мешает спать всей семье.','','B1','A7',797,'шкодити, завдавати шкоди','Шум заважає спати всій родині.',''),
('w:produzir','b1','produzir','глаг.','производить, выпускать','A região produz vinho desde o tempo dos romanos.','Здесь делают вино со времён римлян.','','B1','B3',798,'виробляти, випускати','Тут роблять вино від часів римлян.',''),
('w:propor','b1','propor','глаг.','предлагать','Propôs que adiássemos a reunião para quinta-feira.','Он предложил перенести встречу на четверг.','propor-se a — вызваться сделать что-то','B1','A8',799,'вносити пропозицію','Він запропонував перенести зустріч на четвер.','propor-se a — зголоситися щось зробити')
insert into public.pt_words (id, deck_id, word, pos, ru, ex, exru, note, level, tema, sort, uk, exuk, noteuk) values
('w:proteger','b1','proteger','глаг.','защищать','Este creme protege a pele do sol forte.','Этот крем защищает кожу от сильного солнца.','','B1','A7',800,'захищати','Цей крем захищає шкіру від сильного сонця.',''),
('w:publicar','b1','publicar','глаг.','публиковать, издавать','Publicou o primeiro romance aos cinquenta anos.','Первый роман он издал в пятьдесят.','','B1','B4',801,'публікувати, видавати','Перший роман він видав у п’ятдесят.',''),
('w:registar','b1','registar','глаг.','регистрировать, оформлять','Registei a morada nova no portal das finanças.','Новый адрес я зарегистрировал на портале налоговой.','В Португалии registar, без лишней s','B1','B9',802,'реєструвати, оформлювати','Нову адресу я зареєстрував на порталі податкової.','У Португалії registar, без зайвої s'),
('w:renovar','b1','renovar','глаг.','продлевать, обновлять','Tenho de renovar o cartão de cidadão este mês.','В этом месяце мне нужно продлить удостоверение личности.','','B1','B9',803,'продовжувати, оновлювати','Цього місяця мені треба продовжити картку громадянина.',''),
('w:resistir','b1','resistir','глаг.','сопротивляться, устоять','Não resisti e comprei mais um pastel de nata.','Я не удержался и купил ещё одно пирожное.','resistir a — требует a','B1','A7',804,'чинити опір, встояти','Я не втримався й купив ще одне тістечко.','resistir a — потребує a'),
('w:respeitar','b1','respeitar','глаг.','уважать; соблюдать','É preciso respeitar o horário de silêncio do prédio.','Часы тишины в доме нужно соблюдать.','','B1','B1',805,'поважати; дотримуватися','Години тиші в будинку треба дотримуватися.',''),
('w:resultar','b1','resultar','глаг.','получаться, приводить к','A ideia resultou melhor do que esperávamos.','Задумка получилась лучше, чем мы ожидали.','resultar em — привести к чему-то','B1','A9',806,'виходити, призводити','Задум вийшов кращим, ніж ми сподівалися.','resultar em — призвести до чогось'),
('w:reunir','b1','reunir','глаг.','собирать, объединять','A feira reúne artesãos de todo o país.','Ярмарка собирает ремесленников со всей страны.','reunir-se — собираться, встречаться','B1','A5',807,'збирати, об’єднувати','Ярмарок збирає ремісників з усієї країни.','reunir-se — збиратися, зустрічатися'),
('w:sofrer','b1','sofrer','глаг.','страдать, мучиться','Sofre de dores nas costas desde o acidente.','После аварии он страдает от болей в спине.','sofrer de — страдать от болезни','B1','B6',808,'страждати, потерпати','Після аварії він потерпає від болів у спині.','sofrer de — потерпати від хвороби'),
('w:suportar','b1','suportar','глаг.','выносить, переносить','Não suporto o barulho das obras logo de manhã.','Терпеть не могу шум стройки с самого утра.','','B1','A7',809,'зносити, витримувати','Терпіти не можу шум будівництва зранку.',''),
('w:surpreender','b1','surpreender','глаг.','удивлять, заставать врасплох','A resposta dela surpreendeu toda a gente.','Её ответ удивил всех.','surpreender-se — удивиться самому','B1','A7',810,'дивувати, заставати зненацька','Її відповідь здивувала всіх.','surpreender-se — здивуватися самому'),
('w:testar','b1','testar','глаг.','проверять, испытывать','Testámos a receita antes de a servir aos convidados.','Мы опробовали рецепт, прежде чем подавать гостям.','','B1','A8',811,'випробовувати','Ми випробували рецепт, перш ніж подавати гостям.',''),
('w:transformar','b1','transformar','глаг.','превращать, преображать','Transformaram o armazém antigo numa galeria de arte.','Старый склад превратили в художественную галерею.','transformar-se em — превратиться во что-то','B1','A6',812,'перетворювати','Старий склад перетворили на художню галерею.','transformar-se em — перетворитися на щось'),
('w:variar','b1','variar','глаг.','различаться, меняться','Os preços variam muito conforme a época do ano.','Цены сильно различаются в зависимости от сезона.','«Para variar» — «для разнообразия»','B1','A6',813,'різнитися, змінюватися','Ціни дуже різняться залежно від пори року.','«Para variar» — «для різноманітності»'),
('w:vencer','b1','vencer','глаг.','выигрывать; истекать о сроке','Venceu o torneio sem perder um único jogo.','Он выиграл турнир, не проиграв ни одного матча.','Второе значение — истечь: o prazo venceu','B1','B4',814,'перемагати; спливати про строк','Він виграв турнір, не програвши жодного матчу.','Друге значення — сплинути: o prazo venceu'),
('w:atitude','b1','a atitude','сущ.','отношение к делу, поведение','Mudou de atitude assim que percebeu o problema.','Он изменил своё отношение, как только понял проблему.','','B1','B1',815,'ставлення до справи, поведінка','Він змінив своє ставлення, щойно зрозумів проблему.',''),
('w:avanço','b1','o avanço','сущ.','продвижение вперёд','Houve um avanço grande nas obras esta semana.','На этой неделе стройка сильно продвинулась.','','B1','A4',816,'поступ уперед','Цього тижня будівництво сильно просунулося.',''),
('w:compromisso','b1','o compromisso','сущ.','обязательство; условленная встреча','Tenho um compromisso às seis, não posso ficar.','У меня в шесть встреча, остаться не могу.','','B1','A8',817,'зобов’язання; домовлена зустріч','У мене о шостій зустріч, лишитися не можу.',''),
('w:crise','b1','a crise','сущ.','кризис','A crise deixou muita gente sem trabalho na região.','Кризис оставил многих в этих краях без работы.','','B1','A7',818,'криза','Криза залишила багатьох у цих краях без роботи.',''),
('w:desafio','b1','o desafio','сущ.','вызов, испытание','Mudar de país foi o maior desafio da vida dela.','Переезд в другую страну стал главным испытанием в её жизни.','Desafiar — бросать вызов','B1','A7',819,'виклик, випробування','Переїзд в іншу країну став найбільшим випробуванням у її житті.','Desafiar — кидати виклик'),
('w:discussão','b1','a discussão','сущ.','обсуждение, спор','A discussão sobre o condomínio durou duas horas.','Обсуждение расходов на дом заняло два часа.','','B1','A8',820,'обговорення, суперечка','Обговорення витрат на будинок тривало дві години.',''),
('w:esforço','b1','o esforço','сущ.','усилие','Com algum esforço, conseguimos acabar a tempo.','Ценой некоторых усилий мы успели вовремя.','Fazer um esforço — постараться','B1','A7',821,'зусилля','Ціною певних зусиль ми встигли вчасно.','Fazer um esforço — постаратися'),
('w:falha','b1','a falha','сущ.','сбой, промах','Houve uma falha de energia em todo o bairro.','Во всём квартале случился сбой электроснабжения.','','B1','A7',822,'збій, схибка','У всьому кварталі стався збій електропостачання.',''),
('w:fonte','b1','a fonte','сущ.','источник','O jornal não revelou a fonte da informação.','Газета не раскрыла источник сведений.','Также фонтан и родник','B1','A9',823,'джерело','Газета не розкрила джерело відомостей.','Також фонтан і криниця'),
('w:hipótese','b1','a hipótese','сущ.','предположение; возможность','Não pomos de lado a hipótese de mudar de casa.','Мы не исключаем возможности переехать.','«Nem por hipótese!» — «ни в коем случае!»','B1','A8',824,'припущення; можливість','Ми не відкидаємо можливості переїхати.','«Nem por hipótese!» — «у жодному разі!»'),
('w:iniciativa','b1','a iniciativa','сущ.','инициатива, почин','A iniciativa partiu dos próprios moradores do prédio.','Инициатива исходила от самих жильцов дома.','Ter iniciativa — быть инициативным','B1','A8',825,'ініціатива, почин','Ініціатива йшла від самих мешканців будинку.','Ter iniciativa — бути ініціативним'),
('w:meta','b1','a meta','сущ.','рубеж, к которому стремятся','A minha meta é ler um livro por mês.','Моя цель — читать по книге в месяц.','Также финиш в соревновании','B1','A7',826,'рубіж, до якого прагнуть','Моя мета — читати по книжці на місяць.','Також фініш у змаганні'),
('w:método','b1','o método','сущ.','метод, способ','Cada professor tem o seu método de ensinar.','У каждого учителя свой метод преподавания.','','B1','A8',827,'метод, методика','У кожного вчителя свій метод викладання.',''),
('w:modelo','b1','o modelo','сущ.','модель, образец','Este modelo de máquina gasta menos água.','Эта модель машинки расходует меньше воды.','','B1','A6',828,'модель, зразок','Ця модель машинки витрачає менше води.',''),
('w:nível','b1','o nível','сущ.','уровень','O nível do rio subiu muito depois das chuvas.','После дождей уровень реки сильно поднялся.','Nível de português — уровень владения языком','B1','A5',829,'рівень','Після дощів рівень річки сильно піднявся.','Nível de português — рівень володіння мовою'),
('w:noção','b1','a noção','сущ.','представление о чём-то','Não faço a mínima noção de onde ele mora.','Понятия не имею, где он живёт.','«Não faço ideia» — то же самое','B1','A8',830,'уявлення про щось','Не маю жодного уявлення, де він живе.','«Não faço ideia» — те саме'),
('w:objetivo','b1','o objetivo','сущ.','цель, задача','O objetivo do curso é falar sem medo.','Цель курса — заговорить без страха.','','B1','A7',831,'мета, ціль','Мета курсу — заговорити без страху.',''),
('w:obrigação','b1','a obrigação','сущ.','обязанность','Pagar o condomínio é obrigação de todos os moradores.','Платить за содержание дома обязаны все жильцы.','','B1','A9',832,'обов’язок','Платити за утримання будинку зобов’язані всі мешканці.',''),
('w:oportunidade','b1','a oportunidade','сущ.','удобный случай','Foi a oportunidade que ele esperava há anos.','Это была возможность, которой он ждал годами.','','B1','A7',833,'слушна нагода','Це була нагода, на яку він чекав роками.',''),
('w:política','b1','a política','сущ.','политика','Não gosta de falar de política ao jantar.','Он не любит говорить о политике за ужином.','Также «курс, линия»: a política da empresa','B1','B9',834,'політика','Він не любить говорити про політику за вечерею.','Також «курс, лінія»: a política da empresa'),
('w:possibilidade','b1','a possibilidade','сущ.','вероятность','Há a possibilidade de chover ao fim da tarde.','Есть вероятность, что под вечер пойдёт дождь.','','B1','A8',835,'імовірність','Є ймовірність, що надвечір піде дощ.',''),
('w:prática','b1','a prática','сущ.','практика, применение','Na prática, o horário nunca é cumprido.','На практике расписание никогда не соблюдается.','Na prática — на деле','B1','B3',836,'практика, застосування','На практиці розкладу ніколи не дотримуються.','Na prática — на ділі'),
('w:processo','b1','o processo','сущ.','процедура; дело','O processo de renovação demora cerca de um mês.','Процедура продления занимает около месяца.','Также судебное дело','B1','B9',837,'процедура; справа','Процедура продовження триває близько місяця.','Також судова справа'),
('w:progresso','b1','o progresso','сущ.','успехи, продвижение','Fez progressos grandes desde que começou as aulas.','С начала занятий он сильно продвинулся.','Обычно во мн. ч.: fazer progressos','B1','A4',838,'успіхи, поступ','Від початку занять він сильно просунувся.','Зазвичай у множині: fazer progressos'),
